using Inventory.Legacy;

namespace Inventory;

/// <summary>Reconciles a counted quantity against the system position.</summary>
public sealed class StockSync
{
    private readonly IStockLedger _ledger;

    public StockSync()
        : this(new InMemoryStockLedger())
    {
    }

    public StockSync(IStockLedger ledger)
    {
        _ledger = ledger ?? throw new ArgumentNullException(nameof(ledger));
    }

    public int Reconcile(StockItem item, int countedQuantity)
    {
        var variance = countedQuantity - item.OnHand;
        _ledger.Record(item.Sku, variance);
        return variance;
    }
}
